CREATE TYPE "PaymentStatus" AS ENUM ('PENDING','AUTHORIZED','PAID','FAILED','CANCELLED','REFUNDED','PARTIALLY_REFUNDED');
CREATE TYPE "PayoutStatus" AS ENUM ('PENDING','BLOCKED','AVAILABLE','SCHEDULED','PAID','CANCELLED');
CREATE TYPE "LedgerEntryType" AS ENUM ('SALE','COMMISSION','PROVIDER_FEE','PAYOUT','REFUND','ADJUSTMENT');
CREATE TABLE "Payment" ("id" TEXT NOT NULL, "orderId" TEXT NOT NULL, "provider" TEXT NOT NULL DEFAULT 'TEST_PENDING', "providerPaymentId" TEXT, "amount" DECIMAL(12,2) NOT NULL, "currency" VARCHAR(3) NOT NULL DEFAULT 'TRY', "status" "PaymentStatus" NOT NULL DEFAULT 'PENDING', "paymentMethod" VARCHAR(80), "metadata" JSONB, "paidAt" TIMESTAMP(3), "failedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Payment_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Payment_orderId_key" ON "Payment"("orderId"); CREATE UNIQUE INDEX "Payment_providerPaymentId_key" ON "Payment"("providerPaymentId"); ALTER TABLE "Payment" ADD CONSTRAINT "Payment_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "SellerPayout" ("id" TEXT NOT NULL,"sellerId" TEXT NOT NULL,"orderId" TEXT NOT NULL,"orderItemId" TEXT NOT NULL,"grossAmount" DECIMAL(12,2) NOT NULL,"commissionAmount" DECIMAL(12,2) NOT NULL,"providerFeeAmount" DECIMAL(12,2) NOT NULL DEFAULT 0,"netAmount" DECIMAL(12,2) NOT NULL,"currency" VARCHAR(3) NOT NULL DEFAULT 'TRY',"status" "PayoutStatus" NOT NULL DEFAULT 'PENDING',"availableAt" TIMESTAMP(3),"paidAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SellerPayout_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "SellerPayout_orderItemId_key" ON "SellerPayout"("orderItemId"); CREATE INDEX "SellerPayout_sellerId_status_createdAt_idx" ON "SellerPayout"("sellerId","status","createdAt"); ALTER TABLE "SellerPayout" ADD CONSTRAINT "SellerPayout_sellerId_fkey" FOREIGN KEY ("sellerId") REFERENCES "SellerProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "SellerPayout" ADD CONSTRAINT "SellerPayout_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "SellerPayout" ADD CONSTRAINT "SellerPayout_orderItemId_fkey" FOREIGN KEY ("orderItemId") REFERENCES "OrderItem"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "FinancialLedgerEntry" ("id" TEXT NOT NULL,"sellerId" TEXT NOT NULL,"orderItemId" TEXT NOT NULL,"payoutId" TEXT,"type" "LedgerEntryType" NOT NULL,"amount" DECIMAL(12,2) NOT NULL,"currency" VARCHAR(3) NOT NULL DEFAULT 'TRY',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "FinancialLedgerEntry_pkey" PRIMARY KEY ("id")); CREATE INDEX "FinancialLedgerEntry_sellerId_createdAt_idx" ON "FinancialLedgerEntry"("sellerId","createdAt"); CREATE INDEX "FinancialLedgerEntry_orderItemId_type_idx" ON "FinancialLedgerEntry"("orderItemId","type"); ALTER TABLE "FinancialLedgerEntry" ADD CONSTRAINT "FinancialLedgerEntry_sellerId_fkey" FOREIGN KEY ("sellerId") REFERENCES "SellerProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "FinancialLedgerEntry" ADD CONSTRAINT "FinancialLedgerEntry_orderItemId_fkey" FOREIGN KEY ("orderItemId") REFERENCES "OrderItem"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "FinancialLedgerEntry" ADD CONSTRAINT "FinancialLedgerEntry_payoutId_fkey" FOREIGN KEY ("payoutId") REFERENCES "SellerPayout"("id") ON DELETE SET NULL ON UPDATE CASCADE;
